function getRegionForUnit(unit) {
  if (!unit) return "JAMALI";
  const u = String(unit).toUpperCase();
  if (u.includes("JBB") || u.includes("JBT") || u.includes("JBM") || u.includes("JAWA") || u.includes("JAMALI")) return "JAMALI";
  if (u.includes("P3BS") || u.includes("SUMATERA") || u.includes("BABEL")) return "SUMATERA";
  if (u.includes("KAL")) return "KALIMANTAN";
  return "SULAWESI";
}

function getMatrixColForTier(unit, tegangan, tier) {
  const reg = getRegionForUnit(unit);
  const matrix = TIER_MAPPING_MATRIX[reg] || TIER_MAPPING_MATRIX.JAMALI;
  const voltNum = parseInt(String(tegangan).replace(/\D/g, "")) || 150;
  
  let voltKey = 150;
  if (voltNum >= 400) voltKey = 500;
  else if (voltNum >= 200) voltKey = 275;
  else if (voltNum >= 100) voltKey = 150;
  else if (voltNum >= 60) voltKey = 70;
  else if (voltNum >= 20) voltKey = 30;

  const voltTable = matrix[voltKey] || matrix[150] || matrix[500];
  const t = parseInt(tier) || 1;
  const col = voltTable ? voltTable[t] : null;
  if (col !== undefined && col !== null) return col;
  return Math.max(1, Math.min(5, 6 - t));
}

